# coding: utf-8
import json
from pathlib import Path
from lesson_authoring import entry as E
B=[['拉丁 fugere；fuga','逃离；逃走']]
W=[
E('refuge','/ˈrefjuːdʒ/','庇护；避难处；让人躲开烦扰的地方','外面有危险或压力，你退到一个能保护自己的地方。','拉丁 re- 回、向后 + fugere 逃，形成 refugium；经古法语 refuge 借入。',B+[['拉丁 re- + fugere → refugium','逃回、退避 → 庇护之处'],['古法语 refuge → 英语 refuge','庇护；避难处']],'take refuge from the rain 是避雨；find refuge in books 是从阅读中得到精神上的安慰或躲开烦扰。它既可指具体地方，也可指保护或慰藉这种作用。','take refuge in；seek refuge from；a refuge for wildlife。','refuge 是地方或保护，refugee 是人。shelter 常强调遮蔽和栖身，refuge 更突出躲开危险或困扰。',('We took refuge in a small café during the storm.','暴风雨来时，我们躲进一家小咖啡馆。'),('For her, the library was a refuge from the noise outside.','对她来说，图书馆是躲开外面喧闹的清静之地。'),sources=['https://www.etymonline.com/word/refuge','https://en.wiktionary.org/wiki/refuge']),
E('refugee','/ˌrefjʊˈdʒiː/','难民；因迫害、冲突等被迫离开本国寻求安全的人','不是轻松换个地方生活，而是原来的家园已无法安全停留或返回。','借自法语 réfugié，是 réfugier 避难的过去分词名词化；远源接拉丁 refugium。不是英语 refuge 现加一个“被逃的人”后缀。',B+[['拉丁 refugium → 法语 refuge／réfugier','庇护 → 寻求庇护'],['法语 réfugié → 英语 refugee','避难的人 → 难民']],'a refugee family 是难民家庭；support refugees 是帮助难民。现代国际保护语境通常涉及人在本国之外，因迫害、武装冲突等无法安全返回；精确身份要看适用定义，不能只凭词根给人归类。','a refugee family；refugee protection；support refugees。','refugee 与 fugitive 不是同义词：前者强调被迫逃离危险，后者常指逃避追捕。也不能把所有迁居者都叫 refugee。',('The community organized language classes for refugee families.','社区为难民家庭组织了语言课。'),('The novel follows a refugee trying to rebuild her life.','小说讲述一位难民努力重建生活的经历。'),sources=['https://www.etymonline.com/word/refugee','https://www.unhcr.org/what-is-a-refugee','https://en.wiktionary.org/wiki/refugee']),
E('fugitive','/ˈfjuːdʒɪtɪv/','逃亡者；在逃的；短暂易逝的〔较书面〕','有个身影正在离开、躲避追踪；抽象事物也可以像这个身影一样一闪而过。','拉丁 fugitivus 来自 fugere 逃；经法语 fugitif 等形式进入英语，形容词也用作指人的名词。',B+[['拉丁 fugitivus → 古法语 fugitif','逃离、在逃的'],['英语 fugitive','在逃者；在逃的；后来也指短暂易逝']],'a fugitive from justice 常指逃避司法追捕的人；a fugitive suspect 是在逃嫌疑人。书面语的 fugitive impressions 则是转瞬即逝的印象，不是印象犯了罪。','a fugitive suspect；a fugitive from justice；fugitive impressions。','fugitive 的现代常用语境带追捕意味，但词本身不等于已经被判有罪。refugee 说难民，不该混称。',('The detective novel begins with a fugitive hiding in a crowded station.','这部侦探小说开场是一名逃亡者藏在拥挤的车站里。'),('The diary preserves fugitive impressions of a city she barely knew.','日记留下了她对一座陌生城市稍纵即逝的印象。'),sources=['https://www.etymonline.com/word/fugitive','https://en.wiktionary.org/wiki/fugitive']),
E('subterfuge','/ˈsʌbtəfjuːdʒ/；美亦 /ˈsʌbtərfjuːdʒ/','诡计；掩饰或逃避的手段','不从正门回答，而是绕到暗处，让别人看不到真实意图。','拉丁 subter 在下面、暗中 + fugere 逃，形成 subterfugere；接中世纪拉丁 subterfugium，经法语或直接借入。',B+[['拉丁 subter + fugere → subterfugere','暗中 + 逃 → 逃避、躲开'],['中世纪拉丁 subterfugium／法语 subterfuge → 英语 subterfuge','规避、掩饰的计谋']],'use subterfuge 是使用掩饰性计谋；a clever subterfuge 是巧妙的障眼法。它可以指一个具体伎俩，也可笼统指这类隐瞒手段，语气通常比 strategy 更负面。','use subterfuge；resort to subterfuge；a deliberate subterfuge。','strategy 只是策略，不必欺骗；subterfuge 强调遮掩、规避或误导。它不是普通物理上的逃跑路线。',('The false invitation was a subterfuge to keep her away from the meeting.','那张假邀请函是为了不让她参加会议而设的诡计。'),('The character relies on subterfuge rather than answering directly.','这个角色靠耍花招应付，而不直接回答。'),sources=['https://www.etymonline.com/word/subterfuge','https://en.wiktionary.org/wiki/subterfuge']),
E('fugue','/fjuːɡ/','赋格曲；赋格〔音乐〕','一个声部先说出主题，其他声部随后加入，像接力追逐同一个旋律想法。','拉丁 fuga 逃离，进入意大利音乐术语 fuga；英语早期形式经意大利语，现代拼写又受法语 fugue 影响。',B+[['意大利 fuga','逃离意象 → 各声部仿佛追逐的音乐写法'],['法语 fugue／英语 fugue','赋格']],'a fugue by Bach 是巴赫的赋格作品；the subject of a fugue 是赋格主题。多个声部依次提出、回应并发展主题，不是把同一段录音机械重复几遍。','a fugue for organ；the subject of a fugue；a prelude and fugue。','fugue 的追逐是帮助理解名称的意象，具体作曲规则比这个比喻复杂。另有精神医学同形术语，不能由音乐义直接推断。',('The pianist played a prelude followed by a fugue.','钢琴家先演奏了前奏曲，接着演奏了一首赋格曲。'),('Listen for the theme as it enters in each voice of the fugue.','听这首赋格时，留意主题如何在各个声部依次出现。'),sources=['https://www.etymonline.com/word/fugue','https://en.wiktionary.org/wiki/fugue']),
E('centrifugation','英 /ˌsentrɪfjuːˈɡeɪʃən/；美 /ˌsentrəfjuˈɡeɪʃən/','离心分离；离心处理','让样品快速旋转，利用不同成分沉降行为的差异，把混在一起的东西分开。','centrifuge 离心机／离心处理 + -ation；centri- 中心与 fug- 逃离，来自“离开中心”的命名意象。',[['近代拉丁 centrum + fugere → centrifugus','中心 + 逃离 → 离心的'],['法语 centrifuge → 英语 centrifuge','离心机；离心处理'],['centrifuge → centrifugation','离心分离这一过程']],'after centrifugation 是离心处理后；separate by centrifugation 是利用离心分离。常见于实验方法描述，分离效果取决于样品和处理条件，不是任何混合物转一下都能完全分开。','separation by centrifugation；after centrifugation；a centrifugation step。','centrifuge 是设备或动词，centrifugation 是过程。filtration 通过过滤介质分离，原理不同。',('The particles were separated from the liquid by centrifugation.','颗粒通过离心处理从液体中分离出来。'),('The report describes the sample before and after centrifugation.','报告描述了样品在离心处理前后的状态。'),sources=['https://www.merriam-webster.com/dictionary/centrifugation','https://en.wiktionary.org/wiki/centrifugation','https://www.etymonline.com/word/centrifuge'])
]
ROOT=dict(id='C0454',meaning='逃；逃离；避开',core='FUG = FLEE',image='想象一个身影离开危险：他逃向保护自己的 refuge；有时逃避的是追捕，有时用 subterfuge 躲开正面回应。音乐与科技词借走了“追逐、离开”的意象。',intro='来自拉丁 fugere“逃离”，相关名词 fuga 表逃走。fugitive 保留 fugit- 形式；refuge、refugee 经法语，拼写和读音都有变化。centrifugal、centrifuge 用“离开中心”命名；fugue 用声部仿佛相互追逐的画面帮助理解。',forms='re- 回、退 + fugere → refugium，接出 refuge 的保护之处。refugee 来自法语过去分词名词化，不宜硬拆成英语“被逃的人”。subter- 暗中、在下，形成 subterfuge 的规避意象。',branches=[['逃离与庇护','refuge, refugee, fugitive'],['隐蔽规避','subterfuge'],['声部追逐','fugue'],['离开中心的命名','centrifugal, centrifuge, centrifugation']],contrasts='refuge 是庇护或避难处，refugee 是难民，fugitive 常指在逃者。词根相同不代表处境或身份相同。centrifugal 的字面意象帮助认词，不替代对旋转运动的完整物理解释。',practice='In the novel, the fugitive seeks refuge in a quiet village and uses subterfuge to hide his identity.\n\n小说中，逃亡者在安静的村庄寻找藏身处，并用计谋隐瞒身份。',words=[x['word'] for x in W]+['centrifugal','centrifuge'],exclude={'fugacious':'较生僻形容词暂略，常用 fleeting 可表达相近意思'})
if __name__=='__main__':
 for name,data in [('roots_fug',[ROOT]),('words_fug',W)]:Path('.cache/batch200/drafts/root/'+name+'.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 print(len(W),sum(len(x['examples']) for x in W))
